diagram='''<figure><svg viewBox="0 0 900 280" role="img" aria-labelledby="s-title s-desc" xmlns="http://www.w3.org/2000/svg"><title id="s-title">A body made by four terms</title><desc id="s-desc">Four colored controls surround a responsive specimen whose shape keeps changing.</desc><rect width="900" height="280" rx="18" fill="#121827"/><path d="M190 70L450 140M710 70L450 140M190 220L450 140M710 220L450 140" stroke="#8fc7d5" stroke-width="5"/><circle cx="190" cy="70" r="38" fill="#e9b86f"/><circle cx="710" cy="70" r="38" fill="#77b9d6"/><circle cx="190" cy="220" r="38" fill="#d887b7"/><circle cx="710" cy="220" r="38" fill="#85c89a"/><path d="M450 72c60 15 86 54 62 91-19 30-74 45-111 12-38-35-22-87 49-103z" fill="#f0d48c" stroke="#f5f0ff" stroke-width="5"/><g font-family="system-ui,sans-serif" text-anchor="middle" fill="#121827"><text x="190" y="76" font-size="18">F</text><text x="710" y="76" font-size="18">E</text><text x="190" y="226" font-size="18">λ</text><text x="710" y="226" font-size="18">φ</text></g><text x="450" y="42" font-family="system-ui,sans-serif" text-anchor="middle" fill="#f5f0ff" font-size="22">the formula becomes a body</text><text x="450" y="260" font-family="system-ui,sans-serif" text-anchor="middle" fill="#f5f0ff" font-size="17">change can preserve a form without fixing it</text></svg><figcaption>The specimen turns QFEP’s vocabulary into a question about continuity, resistance, and variation.</figcaption></figure>'''
